async function request<T>(token:string, path:string, init?:RequestInit):Promise<T> {
  const response=await authenticatedFetch(path,token,{...init,headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`,...init?.headers}})
  if(!response.ok){const body=await response.json().catch(()=>null);const validation=body?.errors&&typeof body.errors==='object'?Object.values(body.errors).flat().find(value=>typeof value==='string'):undefined;throw new Error(body?.error??validation??body?.title??`İstek başarısız (${response.status})`)}
  return response.status===204?undefined as T:response.json()
}
