function localizeHrError(error:unknown,isEn:boolean):string {
  const message=error instanceof Error?error.message:String(error)
  if(!isEn)return message
  const status=message.match(/^İstek başarısız \((\d{3})\)$/)
  if(status)return `Request failed (${status[1]}).`
  if(message==='One or more validation errors occurred.')return 'Please check the entered information and try again.'
  if(message.startsWith("'")&&message.includes("' parametresinin '")&&message.includes('yürürlük aralıkları çakışamaz.'))return 'Effective date ranges for the same parameter and profile cannot overlap.'
  return hrErrorTranslations[message]??message
}

function hrStatusLabel(status:string,isEn:boolean):string {
  const labels:Record<string,[string,string]>={Active:['Aktif','Active'],Terminated:['Ayrıldı','Terminated'],Requested:['Bekliyor','Pending'],PendingApproval:['Onay bekliyor','Pending approval'],Approved:['Onaylandı','Approved'],Finalized:['Kesinleştirildi (iç sonuç)','Finalized (internal result)'],Rejected:['Reddedildi','Rejected'],Cancelled:['İptal edildi','Cancelled'],Draft:['Taslak','Draft']}
  return labels[status]?.[isEn?1:0]??status
}

