  async function generatePayroll1003A(){if(!payroll1003ATarget)return;setBusy(true);setError('');setMessage('');try{let payload:unknown;try{payload=JSON.parse(payroll1003AJson)}catch{throw new Error(tr('1003A verileri geçerli JSON değil.','1003A data is not valid JSON.'))}const response=await authenticatedFetch(`/api/hr/payroll/runs/${payroll1003ATarget.runId}/calculations/${payroll1003ATarget.calculationId}/1003a-xml`,token,{method:'POST',body:JSON.stringify(payload)});if(!response.ok){const body=await response.json().catch(()=>null);const details=body?.errors?.declaration?.join?.(' ');throw new Error(details??body?.error??body?.title??`İstek başarısız (${response.status})`)}const blob=await response.blob();const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;const disposition=response.headers.get('Content-Disposition')??'';const encodedName=disposition.match(/filename\*=UTF-8''([^;]+)/i)?.[1];const plainName=disposition.match(/filename="?([^";]+)"?/i)?.[1];let downloadName='MUHSGK_21_beyan.xml';try{downloadName=encodedName?decodeURIComponent(encodedName):plainName??downloadName}catch{downloadName=plainName??downloadName}link.download=downloadName.replace(/[\\/:*?"<>|]/g,'_');link.click();window.setTimeout(()=>URL.revokeObjectURL(url),1000);setMessage(tr('1003A XML oluşturuldu ve GİB XSD yapısına göre doğrulandı. GİB iş kuralları ve kabulü ayrıca kontrol edilmelidir.','1003A XML generated and validated against the GIB XSD. GIB business rules and acceptance still require separate validation.'))}catch(e){setError(localizeHrError(e,isEn))}finally{setBusy(false)}}
