  async function importEmployeeRows(rows:Record<string,unknown>[]){if(!admin)throw new Error(tr('Personel içe aktarma yalnızca firma yöneticisine açıktır.','Employee imports are restricted to tenant administrators.'));let imported=0;for(let index=0;index<rows.length;index++){const row=rows[index],fields=Object.entries(row).map(([key,value])=>[key.trim().toLocaleLowerCase('tr-TR'),String(value??'').trim()] as const),read=(...names:string[])=>fields.find(([key])=>names.includes(key))?.[1]??'',personnelCode=read('personel kodu','personnel code','code'),fullName=read('ad soyad','full name','name');if(!personnelCode||!fullName)throw new Error(tr(`Excel satır ${index+2}: personel kodu ve ad soyad zorunludur.`,`Excel row ${index+2}: personnel code and full name are required.`));try{await request<Employee>(token,'/api/hr/employees/',{method:'POST',body:JSON.stringify({personnelCode,fullName,department:read('departman','department')||null,jobTitle:read('görev','job title')||null,workEmail:read('iş e-postası','work email','email')||null,hireDate:read('işe giriş tarihi','hire date')||today,terminationDate:null,userId:null})});imported++}catch(error){throw new Error(tr(`${imported} personel eklendi. Excel satır ${index+2} kaydedilemedi: ${(error as Error).message}`,`${imported} employees were added. Excel row ${index+2} failed: ${(error as Error).message}`))}}await reload();setMessage(tr(`${imported} personel Excel'den aktarıldı.`,`${imported} employees imported from Excel.`))}
