      {compensationAccess.view&&<div className="hr-panel"><h3>{tr('Önceki işveren beyanları','Prior-employer declarations')}</h3><div className="hr-table-wrap"><AdvancedDataGrid className="hr-table"><thead><tr><th>{tr('Personel','Employee')}</th><th>{tr('Yıl / sürüm','Year / version')}</th><th>{tr('Beyan türü','Declaration')}</th><th>{tr('Matrahlar','Base entries')}</th><th>{tr('Kanıt ref.','Evidence ref.')}</th><th>{tr('Durum','Status')}</th><th>{tr('İşlem','Action')}</th></tr></thead><tbody>{priorBases.map(x=><tr key={x.id}><td>{x.employee}</td><td>{x.taxYear} · v{x.version}</td><td>{x.declarationKind==='HasPriorEmployer'?tr('Önceki işveren var','Prior employer exists'):tr('Önceki işveren yok','No prior employer')}</td><td><details><summary>{tr('Görüntüle','View')}</summary><pre>{JSON.stringify(JSON.parse(x.baseEntriesJson),null,2)}</pre></details></td><td>{x.evidenceReference}</td><td><span className="hr-status">{hrStatusLabel(x.status,isEn)}</span></td><td>{compensationAccess.approve&&x.canApprove&&<div className="hr-actions"><button className="secondary" disabled={busy} onClick={()=>void submit(()=>request(token,`/api/hr/payroll/compensation/prior-employer-tax-bases/${x.id}/approve`,{method:'POST',body:JSON.stringify({rowVersion:x.rowVersion})}),tr('Beyan onaylandı.','Declaration approved.'))}><Check size={15}/>{tr('Onayla','Approve')}</button><button className="secondary" disabled={busy} onClick={()=>void submit(()=>request(token,`/api/hr/payroll/compensation/prior-employer-tax-bases/${x.id}/reject`,{method:'POST',body:JSON.stringify({rowVersion:x.rowVersion})}),tr('Beyan reddedildi.','Declaration rejected.'))}>{tr('Reddet','Reject')}</button></div>}</td></tr>)}{!priorBases.length&&<tr><td colSpan={7}>{tr('Beyan yok.','No declarations.')}</td></tr>}</tbody></AdvancedDataGrid></div></div>}
